import Base

def answer(result: CompilerWords & U32) -> IO(U32):
  match result:
    case Tuple{_, value}: IO.pure(U32, value)

def main() -> IO(U32):
  answer(CompilerWords.get(CompilerWords.new(Nat.add(1n, 4294967295n)), 0))

import Base

def value(result: CompilerWords & U32) -> U32:
  match result:
    case Tuple{_, word}: word

def duplicate(words: CompilerWords) -> U32:
  U32.add(value(CompilerWords.get(words, 0)), value(CompilerWords.get(words, 1)))

def main() -> U32:
  duplicate(CompilerWords.new(0n))
